23	/**
24	 * Filter the generic stats used in the bulk optimization page.
25	 *
26	 * @since  1.7.1
27	 * @author Grégory Viguier
28	 *
29	 * @param  array $data  The data.
30	 * @param  array $types The folder types. They are passed as array keys.
31	 * @return array
32	 */
33	function imagify_ngg_bulk_stats( $data, $types ) {
34		if ( ! isset( $types['library|ngg'] ) ) {
35			return $data;
36		}
37	
38		add_filter( 'imagify_count_saving_data', 'imagify_ngg_count_saving_data', 8 );
39		$total_saving_data = imagify_count_saving_data();
40		remove_filter( 'imagify_count_saving_data', 'imagify_ngg_count_saving_data', 8 );
41	
42		// Global chart.
43		$data['total_attachments']       += imagify_ngg_count_attachments();
44		$data['unoptimized_attachments'] += imagify_ngg_count_unoptimized_attachments();
45		$data['optimized_attachments']   += imagify_ngg_count_optimized_attachments();
46		$data['errors_attachments']      += imagify_ngg_count_error_attachments();
47		// Stats block.
48		$data['already_optimized_attachments'] += $total_saving_data['count'];
49		$data['original_human']                += $total_saving_data['original_size'];
50		$data['optimized_human']               += $total_saving_data['optimized_size'];
51	
52		return $data;
53	}
