6	/**
7	 * Imagify NextGen Gallery class.
8	 *
9	 * @since  1.5
10	 * @author Jonathan Buttigieg
11	 */
12	class Main {
13		use InstanceGetterTrait;
14	
15		/**
16		 * Class version.
17		 *
18		 * @var string
19		 */
20		const VERSION = '1.1';
21	
22		/**
23		 * Launch the hooks.
24		 *
25		 * @since  1.6.5
26		 * @access public
27		 * @author Grégory Viguier
28		 */
29		public function init() {
30			static $done = false;
31	
32			if ( $done ) {
33				return;
34			}
35			$done = true;
36	
37			add_filter( 'imagify_register_context', [ $this, 'register_context' ] );
38			add_filter( 'imagify_context_class_name', [ $this, 'add_context_class_name' ], 10, 2 );
39			add_filter( 'imagify_process_class_name', [ $this, 'add_process_class_name' ], 10, 2 );
40			add_filter( 'imagify_bulk_class_name', [ $this, 'add_bulk_class_name' ], 10, 2 );
41			add_action( 'init', [ $this, 'add_mixin' ] );
42		}
43	
44		/**
45		 * Register the context used for NGG.
46		 *
47		 * @since  1.9
48		 * @access public
49		 * @author Grégory Viguier
50		 *
51		 * @param  array $contexts An array of context names.
52		 * @return array
53		 */
54		public function register_context( $contexts ) {
55			$contexts[] = 'ngg';
56			return $contexts;
57		}
58	
59		/**
60		 * Filter the name of the class to use to define a context.
61		 *
62		 * @since  1.9
63		 * @access public
64		 * @author Grégory Viguier
65		 *
66		 * @param  int    $class_name The class name.
67		 * @param  string $context    The context name.
68		 * @return string
69		 */
70		public function add_context_class_name( $class_name, $context ) {
71			if ( 'ngg' === $context ) {
72				return '\\Imagify\\ThirdParty\\NGG\\Context\\NGG';
73			}
74	
75			return $class_name;
76		}
77	
78		/**
79		 * Filter the name of the class to use for the optimization.
80		 *
81		 * @since  1.9
82		 * @access public
83		 * @author Grégory Viguier
84		 *
85		 * @param  int    $class_name The class name.
86		 * @param  string $context    The context name.
87		 * @return string
88		 */
89		public function add_process_class_name( $class_name, $context ) {
90			if ( 'ngg' === $context ) {
91				return '\\Imagify\\ThirdParty\\NGG\\Optimization\\Process\\NGG';
92			}
93	
94			return $class_name;
95		}
96	
97		/**
98		 * Filter the name of the class to use for the bulk optimization.
99		 *
100		 * @since  1.9
101		 * @access public
102		 * @author Grégory Viguier
103		 *
104		 * @param  int    $class_name The class name.
105		 * @param  string $context    The context name.
106		 * @return string
107		 */
108		public function add_bulk_class_name( $class_name, $context ) {
109			if ( 'ngg' === $context ) {
110				return '\\Imagify\\ThirdParty\\NGG\\Bulk\\NGG';
111			}
112	
113			return $class_name;
114		}
115	
116		/**
117		 * Add custom NGG mixin to override its functions.
118		 *
119		 * @since  1.5
120		 * @access public
121		 * @author Jonathan Buttigieg
