1	<?php
2	use Imagify\ThirdParty\NGG\DB;
3	
4	defined( 'ABSPATH' ) || exit;
5	
6	/**
7	 * Count number of attachments.
8	 *
9	 * @since 1.5
10	 * @author Jonathan Buttigieg
11	 *
12	 * @return int The number of attachments.
13	 */
14	function imagify_ngg_count_attachments() {
15		global $wpdb;
16		static $count;
17	
18		if ( isset( $count ) ) {
19			return $count;
20		}
21	
22		$table_name = $wpdb->prefix . 'ngg_pictures';
23		$count      = (int) $wpdb->get_var( "SELECT COUNT($table_name.pid) FROM $table_name" ); // WPCS: unprepared SQL ok.
24	
25		return $count;
26	}
27	
28	/**
29	 * Count number of optimized attachments with an error.
30	 *
31	 * @since 1.5
32	 * @author Jonathan Buttigieg
33	 *
34	 * @return int The number of attachments.
35	 */
36	function imagify_ngg_count_error_attachments() {
37		static $count;
38	
39		if ( isset( $count ) ) {
40			return $count;
41		}
42	
43		$ngg_db = DB::get_instance();
44		$key    = $ngg_db->get_primary_key();
45		$count  = (int) $ngg_db->get_var_by( "COUNT($key)", 'status', 'error' );
46	
47		return $count;
48	}
49	
50	/**
51	 * Count number of optimized attachments (by Imagify or an other tool before).
52	 *
53	 * @since 1.5
54	 * @author Jonathan Buttigieg
55	 *
56	 * @return int The number of attachments.
57	 */
58	function imagify_ngg_count_optimized_attachments() {
59		static $count;
60	
61		if ( isset( $count ) ) {
62			return $count;
63		}
64	
65		$ngg_db = DB::get_instance();
66		$key    = $ngg_db->get_primary_key();
67		$count  = (int) $ngg_db->get_var_in( "COUNT($key)", 'status', [ 'success', 'already_optimized' ] );
68	
69		return $count;
70	}
71	
72	/**
73	 * Count number of unoptimized attachments.
74	 *
75	 * @since 1.0
76	 * @author Jonathan Buttigieg
77	 *
78	 * @return int The number of attachments.
79	 */
80	function imagify_ngg_count_unoptimized_attachments() {
81		return imagify_ngg_count_attachments() - imagify_ngg_count_optimized_attachments() - imagify_ngg_count_error_attachments();
82	}
83	
84	/**
85	 * Count percent of optimized attachments.
86	 *
87	 * @since 1.0
88	 * @author Jonathan Buttigieg
89	 *
90	 * @return int The percent of optimized attachments.
91	 */
92	function imagify_ngg_percent_optimized_attachments() {
93		$total_attachments           = imagify_ngg_count_attachments();
94		$total_optimized_attachments = imagify_ngg_count_optimized_attachments();
95	
96		if ( ! $total_attachments || ! $total_optimized_attachments ) {
97			return 0;
98		}
99	
100		return min( round( 100 * $total_optimized_attachments / $total_attachments ), 100 );
101	}
102	
103	/**
104	 * Count percent, original & optimized size of all images optimized by Imagify.
105	 *
106	 * @since  1.5
107	 * @since  1.6.7 Revamped to handle huge libraries.
108	 * @author Jonathan Buttigieg
109	 *
110	 * @param  bool|array $attachments An array containing the keys 'count', 'original_size', and 'optimized_size', or an array of attachments (back compat', deprecated), or false.
111	 * @return array An array containing the keys 'count', 'original_size', and 'optimized_size'.
112	 */
113	function imagify_ngg_count_saving_data( $attachments ) {
114		global $wpdb;
115	
116		if ( is_array( $attachments ) ) {
117			return $attachments;
118		}
119	
120		/**
121		 * Filter the query to get all optimized NGG attachments.
122		 * 3rd party will be able to override the result.
123		 *
124		 * @since 1.6.7
125		 *
126		 * @param bool|array $attachments An array containing the keys ('count', 'original_size', and 'optimized_size'), or false.
127		 */
128		$attachments = apply_filters( 'imagify_ngg_count_saving_data', false );
129	
130		if ( is_array( $attachments ) ) {
131			return $attachments;
132		}
133	
134		$original_size  = 0;
135		$optimized_size = 0;
136		$count          = 0;
137	
138		/** This filter is documented in /inc/functions/admin-stats.php */
139		$limit  = apply_filters( 'imagify_count_saving_data_limit', 15000 );
140		$limit  = absint( $limit );
141		$offset = 0;
142		$query  = "
143			SELECT data
144			FROM $wpdb->ngg_imagify_data
145			WHERE status = 'success'
146			LIMIT %d, %d";
147	
148		$attachments = $wpdb->get_col( $wpdb->prepare( $query, $offset, $limit ) ); // WPCS: unprepared SQL ok.
149		$wpdb->flush();
150	
151		while ( $attachments ) {
152			$attachments = array_map( 'maybe_unserialize', $attachments );
153	
154			foreach ( $attachments as $attachment_data ) {
155				if ( ! $attachment_data ) {
156					continue;
157				}
158	
159				++$count;
160				$original_data = $attachment_data['sizes']['full'];
161	
162				// Increment the original sizes.
163				$original_size  += $original_data['original_size'] ? $original_data['original_size'] : 0;
164				$optimized_size += $original_data['optimized_size'] ? $original_data['optimized_size'] : 0;
165	
166				unset( $attachment_data['sizes']['full'], $original_data );
167	
168				// Increment the thumbnails sizes.
169				foreach ( $attachment_data['sizes'] as $size_data ) {
170					if ( ! empty( $size_data['success'] ) ) {
171						$original_size  += $size_data['original_size'] ? $size_data['original_size'] : 0;
172						$optimized_size += $size_data['optimized_size'] ? $size_data['optimized_size'] : 0;
173					}
174				}
175	
176				unset( $size_data );
177			}
178	
179			unset( $attachment_data );
180	
181			if ( count( $attachments ) === $limit ) {
182				// Unless we are really unlucky, we still have attachments to fetch.
183				$offset += $limit;
184	
185				$attachments = $wpdb->get_col( $wpdb->prepare( $query, $offset, $limit ) ); // WPCS: unprepared SQL ok.
186				$wpdb->flush();
187			} else {
188				// Save one request, don't go back to the beginning of the loop.
189				$attachments = [];
190			}
191		}
192	
193		return [
194			'count'          => $count,
195			'original_size'  => $original_size,
196			'optimized_size' => $optimized_size,
197		];
198	}
