6	
7	add_action( 'ngg_after_new_images_added', '_imagify_ngg_optimize_attachment', IMAGIFY_INT_MAX, 2 );
8	/**
9	 * Auto-optimize when a new attachment is added to the database (NGG plugin's table), except for images imported from the library.
10	 *
11	 * @since  1.5
12	 * @author Jonathan Buttigieg
13	 *
14	 * @param int   $gallery_id A Gallery ID.
15	 * @param array $image_ids  An array of Ids or objects. Ids which are sucessfully added.
16	 */
17	function _imagify_ngg_optimize_attachment( $gallery_id, $image_ids ) {
18	
19		if ( ! Imagify_Requirements::is_api_key_valid() || ! get_imagify_option( 'auto_optimize' ) ) {
20			return;
21		}
22	
23		$is_maybe_library_import = ! empty( $_POST['action'] ) && 'import_media_library' === $_POST['action'] && ! empty( $_POST['attachment_ids'] ) && is_array( $_POST['attachment_ids'] ); // WPCS: CSRF ok.
24	
25		if ( $is_maybe_library_import && ! empty( $_POST['nextgen_upload_image_sec'] ) ) { // WPCS: CSRF ok.
26			/**
27			 * The images are imported from the library.
28			 * In this case, those images are dealt with in _imagify_ngg_media_library_imported_image_data().
29			 */
30			return;
31		}
32	
33		if ( $is_maybe_library_import && ( ! empty( $_POST['gallery_id'] ) || ! empty( $_POST['gallery_name'] ) ) ) { // WPCS: CSRF ok.
34			/**
35			 * Same thing but for NGG 2.0 probably.
36			 */
37			return;
38		}
39	
40		foreach ( $image_ids as $image ) {
41			if ( is_numeric( $image ) ) {
42				$image_id = (int) $image;
43			} elseif ( is_object( $image ) && ! empty( $image->pid ) ) {
44				$image_id = (int) $image->pid;
45			} else {
46				$image_id = 0;
47			}
48	
49			if ( ! $image_id ) {
50				continue;
51			}
52	
53			/**
54			 * Allow to prevent automatic optimization for a specific NGG gallery image.
55			 *
56			 * @since  1.6.12
57			 * @author Grégory Viguier
58			 *
59			 * @param bool $optimize   True to optimize, false otherwise.
60			 * @param int  $image_id   Image ID.
61			 * @param int  $gallery_id Gallery ID.
62			 */
63			$optimize = apply_filters( 'imagify_auto_optimize_ngg_gallery_image', true, $image_id, $gallery_id );
64	
65			if ( ! $optimize ) {
66				continue;
67			}
68	
69			$process = imagify_get_optimization_process( $image, 'ngg' );
70	
71			if ( ! $process->is_valid() ) {
72				continue;
73			}
74	
75			if ( $process->get_data()->get_optimization_status() ) {
76				// Optimization already attempted.
77				continue;
78			}
79	
80			$process->optimize();
81		}
82	}
