84	add_filter( 'ngg_medialibrary_imported_image', '_imagify_ngg_media_library_imported_image_data', 10, 2 );
85	/**
86	 * Import Imagify data from a WordPress image to a new NGG image, and optimize the thumbnails.
87	 *
88	 * @since  1.5
89	 * @author Jonathan Buttigieg
90	 *
91	 * @param  object $image      A NGG image object.
92	 * @param  object $attachment An attachment object.
93	 * @return object
94	 */
95	function _imagify_ngg_media_library_imported_image_data( $image, $attachment ) {
96		$wp_process = imagify_get_optimization_process( $attachment->ID, 'wp' );
97	
98		if ( ! $wp_process->is_valid() || ! $wp_process->get_media()->is_supported() ) {
99			return $image;
100		}
101	
102		$wp_data = $wp_process->get_data();
103	
104		if ( ! $wp_data->is_optimized() ) {
105			// The main image is not optimized.
106			return $image;
107		}
108	
109		// Copy the full size data.
110		$wp_full_size_data  = $wp_data->get_size_data();
111		$optimization_level = $wp_data->get_optimization_level();
112	
113		NGG\DB::get_instance()->update(
114			$image->pid,
115			[
116				'pid'                => $image->pid,
117				'optimization_level' => $optimization_level,
118				'status'             => $wp_data->get_optimization_status(),
119				'data'               => [
120					'sizes' => [
121						'full' => $wp_full_size_data,
122					],
123					'stats' => [
124						'original_size'  => $wp_full_size_data['original_size'],
125						'optimized_size' => $wp_full_size_data['optimized_size'],
126						'percent'        => $wp_full_size_data['percent'],
127					],
128				],
129			]
130		);
131	
132		$ngg_process = imagify_get_optimization_process( $image->pid, 'ngg' );
133	
134		if ( ! $ngg_process->is_valid() ) {
135			// WTF.
136			return $image;
137		}
138	
139		// Copy the backup file (we don't want to backup the optimized file if it can be avoided).
140		$ngg_media      = $ngg_process->get_media();
141		$wp_media       = $wp_process->get_media();
142		$wp_backup_path = $wp_media->get_backup_path();
143		$filesystem     = imagify_get_filesystem();
144		$backup_copied  = false;
145	
146		if ( $wp_backup_path ) {
147			$ngg_backup_path = $ngg_media->get_raw_backup_path();
148			$backup_copied   = $filesystem->copy( $wp_backup_path, $ngg_backup_path, true );
149	
150			if ( $backup_copied ) {
151				$filesystem->chmod_file( $ngg_backup_path );
152			}
153		}
154	
155		/**
156		 * Next-gen for the full size.
157		 * Look for an existing copy locally:
158		 * - if it exists, copy it (and its optimization data),
159		 * - if not, add it to the optimization queue.
160		 */
161		$add_full_nextgen = $wp_media->is_image();
162	
163		if ( $add_full_nextgen ) {
164			$formats = [
165				'avif' => $wp_process::AVIF_SUFFIX,
166				'webp' => $wp_process::WEBP_SUFFIX,
167			];
168	
169			foreach ( $formats as $extension => $suffix ) {
170				$wp_full_path_nextgen = false;
171				$nextgen_size_name    = 'full' . $suffix;
172				$wp_nextgen_data      = $wp_data->get_size_data( $nextgen_size_name );
173	
174				// Get the path to the next-gen image if it exists.
175				$wp_full_path_nextgen = $wp_process->get_fullsize_file()->get_path_to_nextgen( $extension );
176	
177				if ( $wp_full_path_nextgen && ! $filesystem->exists( $wp_full_path_nextgen ) ) {
178					$wp_full_path_nextgen = false;
179				}
180	
181				if ( $wp_full_path_nextgen ) {
182					// We know we have a next-gen version. Make sure we have the right data.
183					$wp_nextgen_data['success'] = true;
184	
185					if ( empty( $wp_nextgen_data['original_size'] ) ) {
186						// The next-gen data is missing.
187						$full_size_weight = $wp_full_size_data['original_size'];
188	
189						if ( ! $full_size_weight && $wp_backup_path ) {
190							// For some reason we don't have the original file weight, but we can get it from the backup file.
191							$full_size_weight = $filesystem->size( $wp_backup_path );
192	
193							if ( $full_size_weight ) {
194								$wp_nextgen_data['original_size'] = $full_size_weight;
195							}
196						}
197					}
198	
199					if ( ! empty( $wp_nextgen_data['original_size'] ) && empty( $wp_nextgen_data['optimized_size'] ) ) {
200						// The next-gen file size.
201						$wp_nextgen_data['optimized_size'] = $filesystem->size( $wp_full_path_nextgen );
202					}
203	
204					if ( empty( $wp_nextgen_data['original_size'] ) || empty( $wp_nextgen_data['optimized_size'] ) ) {
205						// We must have both original and optimized sizes.
206						$wp_nextgen_data = [];
207					}
208				}
209	
210				if ( $wp_full_path_nextgen && $wp_nextgen_data ) {
211					// We have the file and the data.
212					// Copy the file.
213					$ngg_full_file         = new File( $ngg_media->get_raw_fullsize_path() );
214					$ngg_full_path_nextgen = $ngg_full_file->get_path_to_nextgen( $extension ); // Destination.
215	
216					if ( $ngg_full_path_nextgen ) {
217						$copied = $filesystem->copy( $wp_full_path_nextgen, $ngg_full_path_nextgen, true );
218	
219						if ( $copied ) {
220							// Success.
221							$filesystem->chmod_file( $ngg_full_path_nextgen );
222							$add_full_nextgen = false;
223						}
224					}
225	
226					if ( ! $add_full_nextgen ) {
227						// The next-gen file has been successfully copied: now, copy the data.
228						$ngg_process->get_data()->update_size_optimization_data( $nextgen_size_name, $wp_nextgen_data );
229					}
230				}
231			}
232		}
233	
234		// Optimize thumbnails.
235		$sizes = $ngg_media->get_media_files();
236		unset( $sizes['full'] );
237	
238		if ( $add_full_nextgen ) {
239			// We could not use a local next-gen copy: ask for a new one.
240	
241			$formats = imagify_nextgen_images_formats();
242	
243			foreach ( $formats as $format ) {
244				if ( 'webp' === $format ) {
245					$suffix = $wp_process::WEBP_SUFFIX;
246				} elseif ( 'avif' === $format ) {
247					$suffix = $wp_process::AVIF_SUFFIX;
248				}
249	
250				$sizes[ 'full' . $suffix ] = [];
251			}
252		}
253	
254		if ( ! $sizes ) {
255			return $image;
256		}
257	
258		$args = [
259			'hook_suffix' => 'optimize_imported_images',
260		];
261	
262		$ngg_process->optimize_sizes( array_keys( $sizes ), $optimization_level, $args );
263	
264		return $image;
265	}
