313	/**
314	 * In case of a dynamic thumbnail, tell if the image must be croped or resized.
315	 *
316	 * @since  1.9
317	 * @author Grégory Viguier
318	 *
319	 * @param  bool           $crop      True to crop the thumbnail, false to resize. Null by default.
320	 * @param  string         $size      Name of the thumbnail size.
321	 * @param  array          $size_data Data of the thumbnail being processed. Contains at least 'width', 'height', and 'path'.
322	 * @param  MediaInterface $media     The MediaInterface instance corresponding to the image being processed.
323	 * @return bool
324	 */
325	function imagify_ngg_should_crop_thumbnail( $crop, $size, $size_data, $media ) {
326		static $data_per_media    = [];
327		static $storage_per_media = [];
328	
329		if ( 'ngg' !== $media->get_context() ) {
330			return $crop;
331		}
332	
333		$media_id = $media->get_id();
334	
335		if ( ! isset( $data_per_media[ $media_id ] ) ) {
336			$image = \nggdb::find_image( $media_id );
337	
338			if ( ! empty( $image->_ngiw ) ) {
339				$storage_per_media[ $media_id ] = $image->_ngiw->get_storage()->object;
340			} else {
341				$storage_per_media[ $media_id ] = \C_Gallery_Storage::get_instance()->object;
342			}
343	
344			$data_per_media[ $media_id ] = $storage_per_media[ $media_id ]->_image_mapper->find( $media_id ); // stdClass Object.
345		}
346	
347		$params = $storage_per_media[ $media_id ]->get_image_size_params( $data_per_media[ $media_id ], $size );
348	
349		return ! empty( $params['crop'] );
350	}
