266		/**
267		 * Create the media thumbnails.
268		 *
269		 * @since  1.9
270		 * @access public
271		 * @author Grégory Viguier
272		 *
273		 * @return bool|WP_Error True on success. A \WP_Error instance on failure.
274		 */
275		public function generate_thumbnails() {
276			if ( ! $this->is_valid() ) {
277				return new \WP_Error( 'invalid_media', __( 'This media is not valid.', 'imagify' ) );
278			}
279	
280			$image_data = $this->storage->_image_mapper->find( $this->get_id() );
281	
282			if ( ! $image_data ) {
283				return new \WP_Error( 'no_ngg_image', __( 'Image not found in NextGen Gallery data.', 'imagify' ) );
284			}
285	
286			if ( empty( $image_data->meta_data['backup'] ) || ! is_array( $image_data->meta_data['backup'] ) ) {
287				$full_path = $this->storage->get_image_abspath( $image_data );
288	
289				$image_data->meta_data['backup'] = [
290					'filename'  => $this->filesystem->file_name( $full_path ), // Yes, $full_path.
291					'width'     => $image_data->meta_data['width'],            // Original image width.
292					'height'    => $image_data->meta_data['height'],           // Original image height.
293					'generated' => microtime(),
294				];
295			}
296	
297			$backup_path = $this->storage->get_image_abspath( $image_data, 'backup' );
298			$failed      = [];
299	
300			foreach ( $this->get_media_files() as $size_name => $size_data ) {
301				if ( 'full' === $size_name ) {
302					continue;
303				}
304	
305				$params    = $this->storage->get_image_size_params( $image_data, $size_name );
306				$thumbnail = @$this->storage->generate_image_clone( // phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged
307					$backup_path,
308					$this->storage->get_image_abspath( $image_data, $size_name ),
309					$params
310				);
311	
312				if ( ! $thumbnail ) {
313					// Failed.
314					$failed[] = $size_name;
315					unset( $image_data->meta_data[ $size_name ] );
316					continue;
317				}
318	
319				$size_meta = [
320					'width'     => 0,
321					'height'    => 0,
322					'filename'  => \M_I18n::mb_basename( $thumbnail->fileName ),
323					'generated' => microtime(),
324				];
325	
326				$dimensions = $this->filesystem->get_image_size( $thumbnail->fileName );
327	
328				if ( $dimensions ) {
329					$size_meta['width']  = $dimensions['width'];
330					$size_meta['height'] = $dimensions['height'];
331				}
332	
333				if ( isset( $params['crop_frame'] ) ) {
334					$size_meta['crop_frame'] = $params['crop_frame'];
335				}
336	
337				$image_data->meta_data[ $size_name ] = $size_meta;
338			}
339	
340			// Keep our property up to date.
341			$this->image->_ngiw->_cache['meta_data'] = $image_data->meta_data;
342			$this->image->_ngiw->_orig_image         = $image_data;
343	
344			$post_id = $this->storage->_image_mapper->save( $image_data );
345	
346			if ( ! $post_id ) {
347				return new \WP_Error( 'meta_data_not_saved', __( 'Related NextGen Gallery data could not be saved.', 'imagify' ) );
348			}
349	
350			if ( $failed ) {
351				return new \WP_Error(
352					'thumbnail_restore_failed',
353					sprintf( _n( '%n thumbnail could not be restored.', '%n thumbnails could not be restored.', count( $failed ), 'imagify' ), count( $failed ) ),
354					[ 'failed_thumbnails' => $failed ]
355				);
356			}
357	
358			return true;
359		}
