366		/**
367		 * Tell if the current media has the required data (the data containing the file paths and thumbnails).
368		 *
369		 * @since  1.9
370		 * @access public
371		 * @author Grégory Viguier
372		 *
373		 * @return bool
374		 */
375		public function has_required_media_data() {
376			static $sizes;
377	
378			if ( ! $this->is_valid() ) {
379				return false;
380			}
381	
382			if ( ! isset( $sizes ) ) {
383				$sizes = $this->get_media_files();
384			}
385	
386			return $sizes && ! empty( $this->image->imagePath );
387		}
