389		/**
390		 * Get the list of the files of this media, including the full size file.
391		 *
392		 * @since  1.9
393		 * @access public
394		 * @author Grégory Viguier
395		 *
396		 * @return array {
397		 *     An array with the size names as keys ('full' is used for the full size file), and arrays of data as values:
398		 *
399		 *     @type string $size      The size name.
400		 *     @type string $path      Absolute path to the file.
401		 *     @type int    $width     The file width.
402		 *     @type int    $height    The file height.
403		 *     @type string $mime-type The file mime type.
404		 *     @type bool   $disabled  True if the size is disabled in the plugin’s settings.
405		 * }
406		 */
407		public function get_media_files() {
408			if ( ! $this->is_valid() ) {
409				return [];
410			}
411	
412			$fullsize_path = $this->get_raw_fullsize_path();
413	
414			if ( ! $fullsize_path ) {
415				return [];
416			}
417	
418			$dimensions = $this->get_dimensions();
419			$all_sizes  = [
420				'full' => [
421					'size'      => 'full',
422					'path'      => $fullsize_path,
423					'width'     => $dimensions['width'],
424					'height'    => $dimensions['height'],
425					'mime-type' => $this->get_mime_type(),
426					'disabled'  => false,
427				],
428			];
429	
430			if ( ! $this->is_image() ) {
431				return $this->filter_media_files( $all_sizes );
432			}
433	
434			// Remove common values (that have no value for us here, lol). Also remove 'full' and 'backup'.
435			$image_data = array_diff_key(
436				$this->image->meta_data,
437				[
438					'full'              => 1,
439					'backup'            => 1,
440					'width'             => 1,
441					'height'            => 1,
442					'md5'               => 1,
443					'aperture'          => 1,
444					'credit'            => 1,
445					'camera'            => 1,
446					'caption'           => 1,
447					'created_timestamp' => 1,
448					'copyright'         => 1,
449					'focal_length'      => 1,
450					'iso'               => 1,
451					'shutter_speed'     => 1,
452					'flash'             => 1,
453					'title'             => 1,
454					'keywords'          => 1,
455					'saved'             => 1,
456				]
457			);
458	
459			if ( ! $image_data ) {
460				return $this->filter_media_files( $all_sizes );
461			}
462	
463			$ngg_data = $this->storage->_image_mapper->find( $this->get_id() );
464	
465			foreach ( $image_data as $size => $size_data ) {
466				if ( ! isset( $size_data['width'], $size_data['height'], $size_data['filename'], $size_data['generated'] ) ) {
467					continue;
468				}
469	
470				$file_type = (object) wp_check_filetype( $size_data['filename'], $this->get_allowed_mime_types() );
471	
472				if ( ! $file_type->type ) {
473					continue;
474				}
475	
476				$all_sizes[ $size ] = [
477					'size'      => $size,
478					'path'      => $this->storage->get_image_abspath( $ngg_data, $size ),
479					'width'     => (int) $size_data['width'],
480					'height'    => (int) $size_data['height'],
481					'mime-type' => $file_type->type,
482					'disabled'  => false,
483				];
484			}
485	
486			return $this->filter_media_files( $all_sizes );
487		}
