489		/**
490		 * If the media is an image, get its width and height.
491		 *
492		 * @since  1.9
493		 * @access public
494		 * @author Grégory Viguier
495		 *
496		 * @return array
497		 */
498		public function get_dimensions() {
499			if ( ! $this->is_image() ) {
500				return [
501					'width'  => 0,
502					'height' => 0,
503				];
504			}
505	
506			return [
507				'width'  => ! empty( $this->image->meta_data['width'] ) ? (int) $this->image->meta_data['width'] : 0,
508				'height' => ! empty( $this->image->meta_data['height'] ) ? (int) $this->image->meta_data['height'] : 0,
509			];
510		}
511	
512		/**
513		 * Update the media data dimensions.
514		 *
515		 * @since  1.9
516		 * @access public
517		 * @author Grégory Viguier
518		 *
519		 * @param array $dimensions {
520		 *     An array containing width and height.
521		 *
522		 *     @type int $width  The image width.
523		 *     @type int $height The image height.
524		 * }
525		 */
526		protected function update_media_data_dimensions( $dimensions ) {
527			$changed = false;
528			$data    = [
529				'width'  => $dimensions['width'],
530				'height' => $dimensions['height'],
531				'md5'    => md5_file( $this->get_raw_fullsize_path() ),
532			];
533	
534			foreach ( $data as $k => $v ) {
535				if ( ! isset( $this->image->meta_data[ $k ] ) || $this->image->meta_data[ $k ] !== $v ) {
536					$this->image->meta_data[ $k ] = $v;
537	
538					$changed = true;
539				}
540			}
541	
542			if ( $changed ) {
543				\nggdb::update_image_meta( $this->id, $this->image->meta_data );
544			}
545		}
546	}
