57		public function generate_image_size( $image, $size, $params = null, $skip_defaults = false ) {
58			// $image could be an object or an (int) image ID.
59			if ( is_numeric( $image ) ) {
60				$image = $this->object->_image_mapper->find( $image );
61			}
62	
63			// If a user adds a watermark, rotates or resizes an image, we restore it.
64			// TO DO - waiting for a hook to be able to re-optimize the original size after restoring.
65			if ( isset( $image->pid ) && ( true === $params['watermark'] || ( isset( $params['rotation'] ) || isset( $params['flip'] ) ) || ( ! empty( $params['width'] ) || ! empty( $params['height'] ) ) ) ) {
66				$process = imagify_get_optimization_process( $image->pid, 'ngg' );
67	
68				if ( $process->is_valid() && $process->get_data()->is_optimized() ) {
69					$process->get_data()->delete_optimization_data();
70				}
71			}
72	
73			return $this->call_parent( 'generate_image_size', $image, $size, $params, $skip_defaults );
